func TestResolveUsesEndpointLoadToRankEquivalentLocalEndpoints(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{Name: "local@desk-a", EndpointName: "desk-a", DefaultModel: "model-a", CostClass: "local"},
					{Name: "local@desk-b", EndpointName: "desk-b", DefaultModel: "model-a", CostClass: "local"},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "local" || model != "model-a" {
				return EndpointLoad{}, false
			}
			switch endpoint {
			case "desk-a":
				return EndpointLoad{LeaseCount: 2, NormalizedLoad: 2.5}, true
			case "desk-b":
				return EndpointLoad{LeaseCount: 0, NormalizedLoad: 0.5}, true
			default:
				return EndpointLoad{}, false
			}
		},
	}

	dec, err := Resolve(Request{Harness: "fiz", Model: "model-a"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Provider != "local@desk-b" || dec.Endpoint != "desk-b" {
		t.Fatalf("decision=%#v, want desk-b as least-loaded equivalent local endpoint", dec)
	}
	if len(dec.Candidates) < 2 {
		t.Fatalf("candidates=%#v, want both endpoints", dec.Candidates)
	}
	if dec.Candidates[0].Provider != "local@desk-b" {
		t.Fatalf("top candidate=%#v, want desk-b", dec.Candidates[0])
	}
}

====
}

func TestCostTiebreakFallsThroughToLocalityWhenCostsMatch(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "cloud",
				Surface:             "x",
				CostClass:           "medium",
				AutoRoutingEligible: true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				DefaultModel:        "m",
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers:           []ProviderEntry{{Name: "cloudp", DefaultModel: "m", CostUSDPer1kTokens: 0.01, CostSource: CostSourceCatalog}},
			},
			{
				Name:                "local",
				Surface:             "x",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				DefaultModel:        "m",
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers:           []ProviderEntry{{Name: "localp", DefaultModel: "m", CostUSDPer1kTokens: 0.01, CostSource: CostSourceCatalog}},
			},
		},
		ObservedLatencyMS: map[string]float64{
			ProviderModelKey("localp", "", "m"): 100,
		},
	}

	dec, err := Resolve(Request{Profile: "smart", ProviderPreference: ProviderPreferenceLocalFirst}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Harness != "local" {
		t.Fatalf("identical cost should fall through to locality: harness=%q", dec.Harness)
	}
}

func TestUnknownCostIsNeutralInTiebreak(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{{
			Name:                "fiz",
			Surface:             "embedded-openai",
			CostClass:           "local",
			AutoRoutingEligible: true,
			Available:           true,
			QuotaOK:             true,
			SubscriptionOK:      true,
			ExactPinSupport:     true,
			SupportsTools:       true,
			Providers: []ProviderEntry{
				{Name: "expensive", DefaultModel: "m", CostUSDPer1kTokens: 0.09, CostSource: CostSourceCatalog},
				{Name: "unknown", DefaultModel: "m", CostSource: CostSourceUnknown},
				{Name: "cheap", DefaultModel: "m", CostUSDPer1kTokens: 0.01, CostSource: CostSourceCatalog},
			},
		}},
	}

	dec, err := Resolve(Request{Harness: "fiz"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if got := []string{dec.Candidates[0].Provider, dec.Candidates[1].Provider, dec.Candidates[2].Provider}; got[0] != "cheap" || got[1] != "unknown" || got[2] != "expensive" {
		t.Fatalf("unknown-cost neutral order=%v, want [cheap unknown expensive]", got)
	}
}

func TestAllUnknownCostSkipsCostTiebreak(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{{
			Name:                "fiz",
			Surface:             "embedded-openai",
			CostClass:           "local",
			AutoRoutingEligible: true,
			Available:           true,
			QuotaOK:             true,
			SubscriptionOK:      true,
			ExactPinSupport:     true,
			SupportsTools:       true,
			Providers: []ProviderEntry{
				{Name: "z-provider", DefaultModel: "m", CostSource: CostSourceUnknown},
				{Name: "a-provider", DefaultModel: "m", CostSource: CostSourceUnknown},
			},
		}},
	}

	dec, err := Resolve(Request{Harness: "fiz"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Provider != "a-provider" {
		t.Fatalf("all-unknown cost should fall through to name: provider=%q", dec.Provider)
	}
}

