// FilterReason* enumerate the canonical disqualification reasons surfaced
// in RouteCandidate.FilterReason and the routing-decision event.
const (
	FilterReasonUnhealthy            = "unhealthy"
	FilterReasonContextTooSmall      = "context_too_small"
	FilterReasonNoToolSupport        = "no_tool_support"
	FilterReasonReasoningUnsupported = "reasoning_unsupported"
	FilterReasonScoredBelowTop       = "scored_below_top"
)

// RouteCandidateComponents breaks down the inputs that fed a candidate's
// final Score so consumers can explain rankings without parsing the
// free-form Reason. Zero fields mean "unknown / not contributing".
type RouteCandidateComponents struct {
	// Power is the catalog model power used by automatic routing. Zero means
	// unknown or not contributing.
	Power int
	// Cost is the per-1k-token cost expressed as a numeric component (USD).
	// Mirrors RouteCandidate.CostUSDPer1kTokens; surfaced here so the event
	// payload carries a single component bundle.
	Cost float64
	// CostClass is the candidate cost class used by the router.
	CostClass string
	// LatencyMS is the observed median latency for this candidate, in
	// milliseconds. Zero when no observations are available.
	LatencyMS float64
	// SpeedTPS is the observed output speed in tokens per second. Zero when
	// no observations are available.
	SpeedTPS float64
	// SuccessRate is the observed success rate (0–1) for this candidate.
	// Negative means insufficient data; zero means unknown.
	SuccessRate float64
	// QuotaOK/QuotaPercentUsed/QuotaTrend are subscription quota inputs used
	// by routing. They are zero values for non-subscription candidates.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
	// Capability is a coarse capability score derived from the candidate's
	// cost class / surface (higher = more capable).
	Capability float64
	// ContextHeadroom is the remaining context after subtracting the request's
	// minimum required prompt window. Zero means unknown or no spare room.
	ContextHeadroom int
}

const (
	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// RouteStickyState describes sticky routing evidence without exposing the
// underlying key.
type RouteStickyState struct {
	KeyPresent     bool    `json:"key_present,omitempty"`
	Assignment     string  `json:"assignment,omitempty"`
	ServerInstance string  `json:"server_instance,omitempty"`
	Reason         string  `json:"reason,omitempty"`
	Bonus          float64 `json:"bonus"`
}

// RouteUtilizationState summarizes the live utilization sample associated
// with a candidate or selected endpoint.
type RouteUtilizationState struct {
	Source         string    `json:"source,omitempty"`
	Freshness      string    `json:"freshness,omitempty"`
	ActiveRequests *int      `json:"active_requests,omitempty"`
	QueuedRequests *int      `json:"queued_requests,omitempty"`
	MaxConcurrency *int      `json:"max_concurrency,omitempty"`
	CachePressure  *float64  `json:"cache_pressure,omitempty"`
	ObservedAt     time.Time `json:"observed_at,omitempty"`
}

// RouteAttempt is caller feedback about one attempted route candidate.
// Status="success" clears matching active failures; any other non-empty status
// records a same-process failure until the service health cooldown expires.
type RouteAttempt struct {
	Harness   string
	Provider  string
	Model     string
	Endpoint  string
	Status    string
	Reason    string
	Error     string
	Duration  time.Duration
	Timestamp time.Time // zero = time.Now()
}

// RouteStatusReport is returned by RouteStatus.
//
// RoutingQuality (ADR-006 §5) is the operator-facing measure of how often
// auto-routing produces an acceptable decision. It is intentionally
// distinct from per-(provider, model) provider-reliability surfaced on
// each RouteCandidateStatus: the two compose, and conflating them is the
// UI bug ADR-006 fixes.
type RouteStatusReport struct {
	Routes          []RouteStatusEntry
	GeneratedAt     time.Time
	GlobalCooldowns []CooldownState
	// RoutingQuality holds the three first-class routing-quality metrics
	// over a recent window (last RouteStatusRoutingQualityWindow requests).
	RoutingQuality RoutingQualityMetrics
}

// RouteStatusRoutingQualityWindow caps how many recent Execute calls
// contribute to RouteStatusReport.RoutingQuality. ADR-006 §5 calls for a
// "recent window"; the constant is exported so operator UIs can label the
// metric appropriately.
const RouteStatusRoutingQualityWindow = 100

// RouteStatusEntry describes the live provider candidates serving one model.
type RouteStatusEntry struct {
	Model                  string
	Strategy               string // informational; route tables are not user-authored
	SelectedEndpoint       string
	SelectedServerInstance string
	Sticky                 RouteStickyState
	Candidates             []RouteCandidateStatus
	LastDecision           *RouteDecision // most recent ResolveRoute result for this key (cached)
	LastDecisionAt         time.Time
}

// RouteCandidateStatus describes a single live provider/model candidate.
//
// ProviderReliabilityRate is the per-(provider, model) observed completion
// rate (the legacy "success rate" metric). Per ADR-006 §5 it is labeled
// "provider reliability" to distinguish it from RoutingQualityMetrics on
// the parent report — the two metrics measure different things and are
// surfaced as separate fields.
type RouteCandidateStatus struct {
	Provider                string
	Model                   string
	ServerInstance          string
	Priority                int
	Healthy                 bool
	Cooldown                *CooldownState
	RecentLatencyMS         float64 // observation-derived; 0 when unavailable
	ProviderReliabilityRate float64 // 0-1; 0 when unavailable. Legacy success-rate field, relabeled per ADR-006 §5 to disambiguate from routing-quality.
}

// ServiceEvent is a contract-level event (mirrors harnesses.Event).
type ServiceEvent = harnesses.Event

// ServiceExecuteRequest is the public ExecuteRequest type per CONTRACT-003.
// See docs/helix/02-design/contracts/CONTRACT-003-fizeau-service.md
// (§"Public types") for the canonical shape; this struct is its in-process
// twin under the agent module.
type ServiceExecuteRequest struct {
	Prompt            string
	SystemPrompt      string
	Model             string
	Provider          string
	Harness           string
	ModelRef          string
	Profile           string
	WorkDir           string
	Temperature       *float32
	TopP              *float64
	TopK              *int
	MinP              *float64
	RepetitionPenalty *float64
	Seed              *int64
	// SamplingSource is the comma-separated layer attribution produced by
	// internal/sampling.Resolve. Plumbed through to the llm.request
	// telemetry event for ADR-007 override-tracking; never on the wire.
	SamplingSource string
	Reasoning      Reasoning
	NoStream       bool
	Permissions    string
	// Tools overrides the built-in native agent tool set when Harness is
	// "fiz". Nil uses the native built-ins for ToolPreset and WorkDir.
	Tools []Tool
	// ToolPreset is passed through to BuiltinToolsForPreset when Tools is nil.
	// Empty uses the default tool set.
	ToolPreset string

package routing

import (
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"
)

func TestRoutingPolicyInvariants(t *testing.T) {
	cases := []struct {
		policyStatement string
		req             Request
		inputs          Inputs
		wantHarness     string
		wantProvider    string
		wantEndpoint    string
		wantModel       string
		wantOnlyHarness string
		wantErrContains string
		wantRejected    map[string]FilterReason
	}{
		{
			policyStatement: "config only sets up provider sources; routing uses discovered inventory",
			req:             Request{Model: "configured-default"},
			inputs:          policyBaseInputs(),
			wantErrContains: "no live endpoint offers a match",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonScoredBelowTop,
				"fiz/paid":  FilterReasonScoredBelowTop,
				"codex/":    FilterReasonScoredBelowTop,
			},
		},
		{
			policyStatement: "if no power provider is configured, use the best cheapest viable model",
			req:             Request{},
			inputs:          policyInputsWithoutPower(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "if local LLMs are available and satisfy constraints, use them",
			req:             Request{MinPower: 7, MaxPower: 7},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "if local/free is unavailable, fall back to the best viable non-local candidate",
			req:             Request{MinPower: 7},
			inputs:          policyInputsWithLocalUnavailable(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
			wantRejected: map[string]FilterReason{
				"fiz/": FilterReasonUnhealthy,
			},
		},
		{
			policyStatement: "if local/free is below requested power, do not select it",
			req:             Request{MinPower: 8, MaxPower: 8},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "paid",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonBelowMinPower,
			},
		},
		{
			policyStatement: "an exact model pin overrides local preference",
			req:             Request{Model: "paid-strong"},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "paid",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonScoredBelowTop,
			},
		},
		{
			policyStatement: "a provider endpoint pin is exclusive",
			req:             Request{Provider: "paid@secondary", Model: "paid-strong"},
			inputs:          policyInputsWithProviderEndpoints(),
			wantHarness:     "fiz",
			wantProvider:    "paid@secondary",
			wantEndpoint:    "secondary",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/paid@primary": FilterReasonPinMismatch,
			},
		},
		{
			policyStatement: "a harness pin is exclusive",
			req:             Request{Harness: "codex", Model: "cloud-frontier"},
			inputs:          policyBaseInputs(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
			wantOnlyHarness: "codex",
		},
		{
			policyStatement: "unknown-power models remain routable when no power bound is requested",
			req:             Request{},
			inputs:          policyInputsWithUnknownPowerModel(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "unknown-power exact pins are allowed",
			req:             Request{Model: "unknown-model"},
			inputs:          policyInputsWithUnknownPowerModel(),
			wantHarness:     "fiz",
			wantProvider:    "unknown",
			wantModel:       "unknown-model",
		},
		{
			policyStatement: "provider/deployment class keeps local community models below cloud frontier when benchmarks tie",
			req:             Request{},
			inputs:          policyInputsWithTiedBenchmarks(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
		},
	}

	for _, tc := range cases {
		t.Run(tc.policyStatement, func(t *testing.T) {
			dec, err := Resolve(tc.req, tc.inputs)
			if tc.wantErrContains != "" {
				if err == nil {
					t.Fatalf("policy_statement=%q: Resolve succeeded with decision=%#v, want error containing %q", tc.policyStatement, dec, tc.wantErrContains)
				}
				if !strings.Contains(err.Error(), tc.wantErrContains) {
					t.Fatalf("policy_statement=%q: error=%q, want contains %q", tc.policyStatement, err.Error(), tc.wantErrContains)
				}
			} else if err != nil {
				t.Fatalf("policy_statement=%q: Resolve error: %v", tc.policyStatement, err)
			}

			if tc.wantHarness != "" && dec.Harness != tc.wantHarness {
				t.Fatalf("policy_statement=%q: harness=%q, want %q; candidates=%s", tc.policyStatement, dec.Harness, tc.wantHarness, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantProvider != "" && dec.Provider != tc.wantProvider {
				t.Fatalf("policy_statement=%q: provider=%q, want %q; candidates=%s", tc.policyStatement, dec.Provider, tc.wantProvider, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantEndpoint != "" && dec.Endpoint != tc.wantEndpoint {
				t.Fatalf("policy_statement=%q: endpoint=%q, want %q; candidates=%s", tc.policyStatement, dec.Endpoint, tc.wantEndpoint, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantModel != "" && dec.Model != tc.wantModel {
				t.Fatalf("policy_statement=%q: model=%q, want %q; candidates=%s", tc.policyStatement, dec.Model, tc.wantModel, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantOnlyHarness != "" {
				for _, candidate := range dec.Candidates {
					if candidate.Harness != tc.wantOnlyHarness {
						t.Fatalf("policy_statement=%q: candidate harness=%q, want only %q; candidates=%s", tc.policyStatement, candidate.Harness, tc.wantOnlyHarness, policyCandidateSummary(dec.Candidates))
					}
				}
			}
			for key, want := range tc.wantRejected {
				candidate, ok := policyCandidateByKey(dec.Candidates, key)
				if !ok {
					t.Fatalf("policy_statement=%q: candidate %q not found in %s", tc.policyStatement, key, policyCandidateSummary(dec.Candidates))
				}
				if candidate.Eligible {
					t.Fatalf("policy_statement=%q: candidate %q remained eligible, want rejected with %q", tc.policyStatement, key, want)
				}
				if candidate.FilterReason != want {
					t.Fatalf("policy_statement=%q: candidate %q filter_reason=%q, want %q; reason=%q", tc.policyStatement, key, candidate.FilterReason, want, candidate.Reason)
				}
			}
		})
	}
}

func TestRoutingPolicyNoCandidateCarriesRejectedTrace(t *testing.T) {
	policyStatement := "no-candidate errors expose rejected candidate reasons for caller retry decisions"
	dec, err := Resolve(Request{MinPower: 9, MaxPower: 9}, policyBaseInputs())
	if err == nil {
		t.Fatalf("policy_statement=%q: Resolve succeeded with decision=%#v, want no viable candidate", policyStatement, dec)
