	var known, unknown Candidate
	for _, c := range dec.Candidates {
		switch c.Provider {
		case "known":
			known = c
		case "unknown":
			unknown = c
		}
	}
	if known.Provider != "known" || unknown.Provider != "unknown" {
		t.Fatalf("candidates=%+v, want known and unknown providers", dec.Candidates)
	}
	if known.Score <= unknown.Score {
		t.Fatalf("known score %.1f should beat unknown score %.1f", known.Score, unknown.Score)
	}
	if known.Components.Utilization <= 0 {
		t.Fatalf("known utilization component=%v, want positive known load", known.Components.Utilization)
	}
	if unknown.Components.Utilization != 0 {
		t.Fatalf("unknown utilization component=%v, want 0 for unknown load", unknown.Components.Utilization)
	}
	if known.Components.StickyAffinity != 0 || unknown.Components.StickyAffinity != 0 {
